{
    targets <- ctx$hold()
    fw <- ctx$features_wide
    instruments <- as.character(fw$instrument_id)
    n <- length(instruments)
    fast <- if (fast_id %in% names(fw)) {
        suppressWarnings(as.numeric(fw[[fast_id]]))
    }
    else {
        rep(NA_real_, n)
    }
    slow <- if (slow_id %in% names(fw)) {
        suppressWarnings(as.numeric(fw[[slow_id]]))
    }
    else {
        rep(NA_real_, n)
    }
    current_above <- is.finite(fast) & is.finite(slow) & fast > slow
    prev_above <- ctx$state_prev$above %||% list()
    was_above <- rep(FALSE, n)
    prev_names <- names(prev_above)
    if (length(prev_above) > 0L && length(prev_names) > 0L) {
        idx <- match(instruments, prev_names)
        ok <- !is.na(idx)
        if (any(ok)) {
            was_above[ok] <- as.logical(unlist(prev_above[idx[ok]], use.names = FALSE))
            was_above[is.na(was_above)] <- FALSE
        }
    }
    cross_up <- current_above & !was_above
    cross_down <- !current_above & was_above
    if (any(cross_up)) 
        targets[instruments[cross_up]] <- 1
    if (any(cross_down)) 
        targets[instruments[cross_down]] <- 0
    list(targets = targets, state_update = list(above = as.list(stats::setNames(current_above, instruments))))
}","strategy_source_capture_method":"deparse_function","strategy_source_hash":"5ffbaebdef371647dfb46f7036bfa513e305aa55354319a6652e48f7020f4030","strategy_type":"functional"}},"strategy_params":[],"strategy_params_hash":"1ea0937c818097b81d749096dc3188a84f3b5795bebda75cfcbcd515a20f8f9d","strategy_params_json":"[]","timing_model":{"args":[],"timing_schema_version":1,"type_id":"next_open","version":1},"universe":{"instrument_ids":["P01","P02","P03","P04","P05","P06","P07","P08","P09","P10","P11","P12"]}}
